(18994, '346513', 11, 83531, '2023-04-21', '2023-04-21', '2023-04-21', 79, '3.884,00', '0,00', '2.812,50', 
'6.696,50', '1970-01-01', '', '2023-04-04', '0,00', '0,00', '6.696,50/april', '', '', '', 116, 
